begin;
create table if not exists public.mme_compensation_grades(grade_id uuid primary key default gen_random_uuid(),grade_code text not null unique,grade_name text not null,currency_code char(3) not null default 'USD',minimum_annual numeric(14,2) not null,midpoint_annual numeric(14,2) not null,maximum_annual numeric(14,2) not null,effective_date date not null,grade_status text not null default 'active' check(grade_status in('active','inactive')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(minimum_annual>=0 and midpoint_annual>=minimum_annual and maximum_annual>=midpoint_annual));
create table if not exists public.mme_employee_compensation(employee_compensation_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),grade_id uuid references public.mme_compensation_grades(grade_id),pay_type text not null check(pay_type in('hourly','salary','commission_only','contract')),base_rate numeric(14,2) not null check(base_rate>=0),currency_code char(3) not null default 'USD',pay_frequency text not null default 'biweekly' check(pay_frequency in('weekly','biweekly','semimonthly','monthly')),effective_date date not null,end_date date,change_reason text not null,approved_by_auth_user_id uuid not null,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(end_date is null or end_date>=effective_date));
create index if not exists mme_employee_compensation_history_idx on public.mme_employee_compensation(employee_auth_user_id,effective_date desc);
create table if not exists public.mme_compensation_change_requests(change_request_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),requested_pay_type text not null check(requested_pay_type in('hourly','salary','commission_only','contract')),requested_base_rate numeric(14,2) not null check(requested_base_rate>=0),currency_code char(3) not null default 'USD',requested_effective_date date not null,reason text not null,request_status text not null default 'pending' check(request_status in('pending','approved','denied','cancelled')),requested_by_auth_user_id uuid not null,reviewed_by_auth_user_id uuid,reviewed_at timestamptz,decision_note text,created_at timestamptz not null default now());
create table if not exists public.mme_employee_incentives(incentive_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),incentive_type text not null check(incentive_type in('commission','bonus','spiff','award','other')),description text not null,amount numeric(14,2) not null check(amount>=0),currency_code char(3) not null default 'USD',period_start date,period_end date,payout_status text not null default 'proposed' check(payout_status in('proposed','approved','sent_to_payroll','paid','voided')),approved_by_auth_user_id uuid,external_payroll_reference text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(period_end is null or period_start is null or period_end>=period_start));
create table if not exists public.mme_benefit_plans(benefit_plan_id uuid primary key default gen_random_uuid(),plan_code text not null unique,plan_name text not null,benefit_type text not null check(benefit_type in('health','dental','vision','life','disability','retirement','wellness','other')),provider_name text,employee_cost numeric(14,2) not null default 0 check(employee_cost>=0),employer_cost numeric(14,2) not null default 0 check(employer_cost>=0),currency_code char(3) not null default 'USD',eligibility_rules text,effective_date date not null,end_date date,plan_status text not null default 'active' check(plan_status in('active','inactive','closed')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(end_date is null or end_date>=effective_date));
create table if not exists public.mme_employee_benefit_enrollments(enrollment_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),benefit_plan_id uuid not null references public.mme_benefit_plans(benefit_plan_id),enrollment_status text not null default 'pending' check(enrollment_status in('pending','active','waived','ended')),coverage_start date,coverage_end date,dependents_count integer not null default 0 check(dependents_count>=0),enrolled_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(coverage_end is null or coverage_start is null or coverage_end>=coverage_start));
create index if not exists mme_benefit_enrollment_employee_idx on public.mme_employee_benefit_enrollments(employee_auth_user_id,enrollment_status);
create table if not exists public.mme_employee_rewards_ledger(reward_entry_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),reward_type text not null check(reward_type in('recognition','gift','discount','wellness','milestone','other')),description text not null,estimated_value numeric(14,2) not null default 0 check(estimated_value>=0),currency_code char(3) not null default 'USD',awarded_at timestamptz not null default now(),awarded_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_compensation_budgets(budget_id uuid primary key default gen_random_uuid(),budget_name text not null,department_id uuid references public.mme_org_departments(department_id),period_start date not null,period_end date not null,budget_amount numeric(16,2) not null check(budget_amount>=0),currency_code char(3) not null default 'USD',assumptions text,budget_status text not null default 'draft' check(budget_status in('draft','submitted','approved','closed')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),check(period_end>=period_start));
do $$declare t text;begin foreach t in array array['mme_compensation_grades','mme_employee_compensation','mme_compensation_change_requests','mme_employee_incentives','mme_benefit_plans','mme_employee_benefit_enrollments','mme_employee_rewards_ledger','mme_compensation_budgets'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;